class FakeOidcClient
  attr_reader :requests

  def initialize(responses)
    @responses = responses
    @requests = []
  end

  def send_request(method, url, headers, body, no_redirect: false)
    @requests << { method: method, url: url, headers: headers, body: body, no_redirect: no_redirect }
    response = @responses.shift || @responses.last
    Petstore::Client::ApiHttpResponse.new(
      status_code: response[:status],
      body: response[:body].is_a?(String) ? response[:body] : response[:body].to_json,
      headers: { 'content-type' => 'application/json' }.merge(response[:headers] || {})
    )
  end
end

# Client whose transport always fails, as when the endpoint is unreachable.
class FailingOidcClient
  # With a discovery response the first request is answered, so a later one
  # (the code exchange) is the one that fails.
  def initialize(error, discovery: nil)
    @error = error
    @discovery = discovery
  end

  def send_request(_method, _url, _headers, _body, **_kwargs)
    raise @error if @discovery.nil?

    response = @discovery
    @discovery = nil
    Petstore::Client::ApiHttpResponse.new(
      status_code: response[:status],
      body: response[:body].to_json,
      headers: { 'content-type' => 'application/json' }
    )
  end
end

# Client that answers every discovery request slowly, so concurrent callers
# overlap, and counts how many discovery requests reached it.
class SlowDiscoveryClient
  attr_reader :discovery_count

  def initialize(discovery)
    @discovery = discovery
    @discovery_count = 0
    @lock = Mutex.new
  end

  def send_request(_method, _url, _headers, _body, **_kwargs)
    @lock.synchronize { @discovery_count += 1 }
    sleep 0.2
    Petstore::Client::ApiHttpResponse.new(
      status_code: 200,
      body: @discovery.to_json,
      headers: { 'content-type' => 'application/json', 'cache-control' => 'max-age=3600' }
    )
  end
end

